window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ebf5dac312ac081"]={"versions": [{"id": "FIG-2ebf5dac312ac081", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Zuordnungs- und Rückverfolgungsdiagramm im Kontext der XML-Schema-Versionierung (AUTOSAR XML Schema / ARXML Serialization Rules). Das Diagramm visualisiert das Mapping zwischen Releases der AUTOSAR Classic Platform (CP) bzw. Adaptive Platform (AP) und den generierten XSD-Schemadateien (<code>AUTOSAR_*.xsd</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Kategorien von Elementen sowie gerichtete Abhängigkeitsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Plattform-Releases (Briefsymbol-Icons):</strong>\n<ul class=\"fig-list\"><li>Classic Platform Releases: <code>CP 4.3.0</code>, <code>CP 4.3.1</code>\n</li><li>Adaptive Platform Releases: <code>AP 17-03</code>, <code>AP 17-10</code>\n</li></ul>\n</li><li><strong>XML-Schema-Dateien (Dokumentsymbol-Icons):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR_4-3-0.xsd</code>\n</li><li><code>AUTOSAR_00042.xsd</code>\n</li><li><code>AUTOSAR_00043.xsd</code>\n</li><li><code>AUTOSAR_00044.xsd</code>\n</li></ul>\n</li><li><strong>Beziehungen / Zuordnungen (gestrichelte Pfeile):</strong>\n<ul class=\"fig-list\"><li><code>CP 4.3.0</code> verweist auf <code>AUTOSAR_4-3-0.xsd</code>, <code>AUTOSAR_00042.xsd</code> und <code>AUTOSAR_00043.xsd</code>.\n</li><li><code>AP 17-03</code> verweist auf <code>AUTOSAR_00042.xsd</code>.\n</li><li><code>AP 17-10</code> verweist auf <code>AUTOSAR_00043.xsd</code> und <code>AUTOSAR_00044.xsd</code>.\n</li><li><code>CP 4.3.1</code> verweist auf <code>AUTOSAR_00044.xsd</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Zuordnungsmodell ohne zeitlichen Ausführungsablauf. Die Pfeile definieren Inklusions- und Kompatibilitätsbeziehungen:</p>\n<ul class=\"fig-list\"><li>Initialisierung/Schnittstellenabbildung: Ältere Classic-Platform-Releases (CP 4.3.0) korrespondieren sowohl mit versionsspezifischen Schemata (<code>AUTOSAR_4-3-0.xsd</code>) als auch mit fortlaufend nummerierten Schemata (<code>AUTOSAR_00042.xsd</code>, <code>AUTOSAR_00043.xsd</code>).\n</li><li>Gemeinsame Schema-Nutzung: Ein Schema kann von mehreren Plattform-Releases referenziert werden (z. B. teilen sich <code>CP 4.3.0</code> und <code>AP 17-03</code> das Schema <code>AUTOSAR_00042.xsd</code>; <code>CP 4.3.0</code> und <code>AP 17-10</code> teilen sich <code>AUTOSAR_00043.xsd</code>; <code>AP 17-10</code> und <code>CP 4.3.1</code> teilen sich <code>AUTOSAR_00044.xsd</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Maßgeblich für die Validierung von ARXML-Modellierungsdateien und Werkzeugketten-Kompatibilität:</p>\n<ul class=\"fig-list\"><li>ARXML-Serialisierer und -Validierer müssen anhand der Release-Identifikatoren auf die korrekte XSD-Schemadatei auflösen.\n</li><li>Kennzeichnung des Wechsels von semantischer Namenskonvention (<code>AUTOSAR_4-3-0.xsd</code>) zu einem einheitlichen fünfstelligen Nummerierungsschema (<code>AUTOSAR_0004x.xsd</code>), welches plattformübergreifend (CP und AP) verwendet wird. Toolhersteller müssen die korrekte Zuordnung der Release-Labels zu den Schemadateien sicherstellen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-11d87540ba6454fa", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Zuordnungs- und Rückverfolgungsdiagramm im Kontext der XML-Schema-Versionierung (AUTOSAR XML Schema / ARXML Serialization Rules). Das Diagramm visualisiert das Mapping zwischen Releases der AUTOSAR Classic Platform (CP) bzw. Adaptive Platform (AP) und den generierten XSD-Schemadateien (<code>AUTOSAR_*.xsd</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Kategorien von Elementen sowie gerichtete Abhängigkeitsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Plattform-Releases (Briefsymbol-Icons):</strong>\n<ul class=\"fig-list\"><li>Classic Platform Releases: <code>CP 4.3.0</code>, <code>CP 4.3.1</code>\n</li><li>Adaptive Platform Releases: <code>AP 17-03</code>, <code>AP 17-10</code>\n</li></ul>\n</li><li><strong>XML-Schema-Dateien (Dokumentsymbol-Icons):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR_4-3-0.xsd</code>\n</li><li><code>AUTOSAR_00042.xsd</code>\n</li><li><code>AUTOSAR_00043.xsd</code>\n</li><li><code>AUTOSAR_00044.xsd</code>\n</li></ul>\n</li><li><strong>Beziehungen / Zuordnungen (gestrichelte Pfeile):</strong>\n<ul class=\"fig-list\"><li><code>CP 4.3.0</code> verweist auf <code>AUTOSAR_4-3-0.xsd</code>, <code>AUTOSAR_00042.xsd</code> und <code>AUTOSAR_00043.xsd</code>.\n</li><li><code>AP 17-03</code> verweist auf <code>AUTOSAR_00042.xsd</code>.\n</li><li><code>AP 17-10</code> verweist auf <code>AUTOSAR_00043.xsd</code> und <code>AUTOSAR_00044.xsd</code>.\n</li><li><code>CP 4.3.1</code> verweist auf <code>AUTOSAR_00044.xsd</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Zuordnungsmodell ohne zeitlichen Ausführungsablauf. Die Pfeile definieren Inklusions- und Kompatibilitätsbeziehungen:</p>\n<ul class=\"fig-list\"><li>Initialisierung/Schnittstellenabbildung: Ältere Classic-Platform-Releases (CP 4.3.0) korrespondieren sowohl mit versionsspezifischen Schemata (<code>AUTOSAR_4-3-0.xsd</code>) als auch mit fortlaufend nummerierten Schemata (<code>AUTOSAR_00042.xsd</code>, <code>AUTOSAR_00043.xsd</code>).\n</li><li>Gemeinsame Schema-Nutzung: Ein Schema kann von mehreren Plattform-Releases referenziert werden (z. B. teilen sich <code>CP 4.3.0</code> und <code>AP 17-03</code> das Schema <code>AUTOSAR_00042.xsd</code>; <code>CP 4.3.0</code> und <code>AP 17-10</code> teilen sich <code>AUTOSAR_00043.xsd</code>; <code>AP 17-10</code> und <code>CP 4.3.1</code> teilen sich <code>AUTOSAR_00044.xsd</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Maßgeblich für die Validierung von ARXML-Modellierungsdateien und Werkzeugketten-Kompatibilität:</p>\n<ul class=\"fig-list\"><li>ARXML-Serialisierer und -Validierer müssen anhand der Release-Identifikatoren auf die korrekte XSD-Schemadatei auflösen.\n</li><li>Kennzeichnung des Wechsels von semantischer Namenskonvention (<code>AUTOSAR_4-3-0.xsd</code>) zu einem einheitlichen fünfstelligen Nummerierungsschema (<code>AUTOSAR_0004x.xsd</code>), welches plattformübergreifend (CP und AP) verwendet wird. Toolhersteller müssen die korrekte Zuordnung der Release-Labels zu den Schemadateien sicherstellen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2ebf5dac312ac081", "to": "FIG-11d87540ba6454fa", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
